<?php $gs=new \Kulturhus\Verein\EventGema($db,(string)$_SESSION['actor'],$registry);$ga=\Kulturhus\Verein\Permissions::actor($db,(string)$_SESSION['actor']);$linked=\Kulturhus\Verein\DocumentCatalog::query($db,'SELECT event_id,event_title FROM event_gema WHERE club_id=? AND entry_id=?',[$ga['club_id'],$r['id']])->fetch(); ?><section class="card"><h2>GEMA-Veranstaltung</h2><?php if($linked): ?><a href="<?= e(url(['view'=>'gema','event'=>$linked['event_id']])) ?>"><?= e($linked['event_title']) ?> · GEMA öffnen</a><?php elseif($finance->canWrite()): ?><p>Passenden Termin auswählen. Datei und Zahlungen bleiben diesem Finanzbeleg zugeordnet.</p><?php foreach(array_merge($gs->upcoming((int)date('Y')),$gs->upcoming((int)date('Y')+1)) as $ge):$gg=$gs->get($ge['event_id']);if($gg['entry_id'])continue; ?><form method="post"><?= csrf().hidden('action','gema-link-invoice').hidden('id',$ge['event_id']).hidden('version',$gg['version']).hidden('entry_id',$r['id']) ?><button class="btn btn-outline theme-secondary secondary">Zuordnen: <?= e($ge['event_date'].' · '.$ge['event_title']) ?></button></form><?php endforeach;endif ?></section>
